def main():
    import sys
    input = sys.stdin.read
    S = input().strip()

    # Count the frequency of each character in S
    frequency = {}
    for char in S:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

    # Count how many characters have each frequency
    freq_count = {}
    for count in frequency.values():
        if count in freq_count:
            freq_count[count] += 1
        else:
            freq_count[count] = 1

    # Check the condition for each frequency
    for count in freq_count.values():
        if count != 0 and count != 2:
            print('No')
            return

    print('Yes')
